# Expected values are SymPy's outputs for the same calls (fps).

skip_unless_full_tests()

skip_on_cran()

x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); n <- Symbol("n", integer = TRUE); k <- Symbol("k", integer = TRUE); f <- Function("f")
mi_fmt <- function(v) if (is.null(v)) "None" else gsub("\n", " ", sstr(v))

test_that("fps match SymPy", {
  expect_equal(mi_fmt(fps_truncate(fps(x ^ 2 + x + 1), 4)), "1 + x + x^2 + O(x^4)")
  expect_equal(mi_fmt(fps_polynomial(fps(x ^ 2 + x + 1))), "x^2 + x + 1")
  expect_equal(mi_fmt(fps_polynomial(fps(log(1 + x)), 6)), "x^5/5 - x^4/4 + x^3/3 - x^2/2 + x")
  expect_equal(mi_fmt(fps_truncate(fps(sin(x), x))), "x - x^3/6 + x^5/120 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(1 / ((x - 1) ^ 2 * (x - 2)), x))), "-1/2 - 5*x/4 - 17*x^2/8 - 49*x^3/16 - 129*x^4/32 - 321*x^5/64 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps((1 + x + x ^ 2 + x ^ 3) / ((x - 1) * (x - 2)), x))), "1/2 + 5*x/4 + 17*x^2/8 + 49*x^3/16 + 113*x^4/32 + 241*x^5/64 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(x / (1 - x - x ^ 2), x, full=TRUE))), "x + x^2 + 2*x^3 + 3*x^4 + 5*x^5 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(1 / (x ^ 2 + 2 * x + 2), x, full=TRUE))), "1/2 - x/2 + x^2/4 - x^4/8 + x^5/8 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(log(1 + x), x))), "x - x^2/2 + x^3/3 - x^4/4 + x^5/5 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(log(1 + x), x, dir=1))), "x - x^2/2 + x^3/3 - x^4/4 + x^5/5 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(log(1 + x), x, dir=-1))), "x - x^2/2 + x^3/3 - x^4/4 + x^5/5 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(log(1 + x), x, 2))), "log(3) - 2/3 - (x - 2)^2/18 + (x - 2)^3/81 - (x - 2)^4/324 + (x - 2)^5/1215 + x/3 + O((x - 2)^6, (x, 2))")
  expect_equal(mi_fmt(fps_truncate(fps(log(1 + x), x, 2, dir=-1))), "log(3) - 2/3 - (2 - x)^2/18 - (2 - x)^3/81 - (2 - x)^4/324 - (2 - x)^5/1215 + x/3 + O((x - 2)^6, (x, 2))")
  expect_equal(mi_fmt(fps_truncate(fps(atan(x), x, full=TRUE))), "x - x^3/3 + x^5/5 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(atan(x), x, full=TRUE, dir=1))), "x - x^3/3 + x^5/5 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(atan(x), x, full=TRUE, dir=-1))), "x - x^3/3 + x^5/5 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(atan(x), x, 2, full=TRUE))), "atan(2) - 2/5 - 2*(x - 2)^2/25 + 11*(x - 2)^3/375 - 6*(x - 2)^4/625 + 41*(x - 2)^5/15625 + x/5 + O((x - 2)^6, (x, 2))")
  expect_equal(mi_fmt(fps_truncate(fps(atan(x), x, 2, full=TRUE, dir=-1))), "atan(2) - 2/5 - 2*(2 - x)^2/25 - 11*(2 - x)^3/375 - 6*(2 - x)^4/625 - 41*(2 - x)^5/15625 + x/5 + O((x - 2)^6, (x, 2))")
  expect_equal(mi_fmt(fps_truncate(fps(x * atan(x) - log(1 + x ^ 2) / 2, x, full=TRUE))), "x^2/2 - x^4/12 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(log((1 + x) / (1 - x)) / 2 - atan(x), x, full=TRUE), n=10)), "2*x^3/3 + 2*x^7/7 + O(x^10)")
  expect_equal(mi_fmt(fps_truncate(fps(sin(x), x))), "x - x^3/6 + x^5/120 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(cos(x), x))), "1 - x^2/2 + x^4/24 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(exp(x), x))), "1 + x + x^2/2 + x^3/6 + x^4/24 + x^5/120 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(atan(x), x))), "x - x^3/3 + x^5/5 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(exp(acos(x)), x))), "exp(pi/2) - x*exp(pi/2) + x^2*exp(pi/2)/2 - x^3*exp(pi/2)/3 + 5*x^4*exp(pi/2)/24 - x^5*exp(pi/2)/6 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(exp(acosh(x)), x))), "I + x - I*x^2/2 - I*x^4/8 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(atan(1 / x), x))), "pi/2 - x + x^3/3 - x^5/5 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(x * atan(x) - log(1 + x ^ 2) / 2, x, rational=FALSE))), "x^2/2 - x^4/12 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(log(1 + x), x, rational=FALSE))), "x - x^2/2 + x^3/3 - x^4/4 + x^5/5 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(airyai(x ^ 2), x))), "3^(5/6)*gamma(1/3)/(6*pi) - 3^(2/3)*x^2/(3*gamma(1/3)) + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(exp(x) * sin(x), x))), "x + x^2 + x^3/3 - x^5/30 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(exp(x) * sin(x) / x, x))), "1 + x + x^2/3 - x^4/30 - x^5/90 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(sin(x) * cos(x), x))), "x - 2*x^3/3 + 2*x^5/15 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(x ^ (-5) * sin(x), x))), "x^(-4) - 1/(6*x^2) + 1/120 - x^2/5040 + x^4/362880 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(x ^ 2 * atan(x), x, rational=FALSE))), "x^3 - x^5/3 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(cos(sqrt(x)) * x, x))), "x - x^2/2 + x^3/24 - x^4/720 + x^5/40320 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(x ^ 2 * cos(sqrt(x)), x))), "x^2 - x^3/2 + x^4/24 - x^5/720 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(x * atan(x) - log(1 + x ^ 2) / 2, x))), "x^2/2 - x^4/12 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(sin(x) + cos(x) - exp(x) + log(1 + x), x))), "x - 3*x^2/2 - x^4/4 + x^5/5 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(1 / x + sin(x), x))), "1/x + x - x^3/6 + x^5/120 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(sin(x) - cos(x) + 1 / (x - 1), x))), "-2 - x^2/2 - 7*x^3/6 - 25*x^4/24 - 119*x^5/120 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(exp(x), x, -oo))), "O(x^(-6), (x, oo))")
  expect_equal(mi_fmt(fps_truncate(fps(erf(x), x, oo))), "1 + O(x^(-6), (x, oo))")
  expect_equal(mi_fmt(fps_truncate(fps(erf(x), x, -oo))), "-1 + O(x^(-6), (x, oo))")
  expect_equal(mi_fmt(fps_truncate(fps(atan(x), x, oo, full=TRUE))), "-1/(5*x^5) + 1/(3*x^3) - 1/x + pi/2 + O(x^(-6), (x, oo))")
  expect_equal(mi_fmt(fps_truncate(fps(atan(x), x, -oo, full=TRUE))), "-1/(5*x^5) + 1/(3*x^3) - 1/x - pi/2 + O(x^(-6), (x, oo))")
  expect_equal(mi_fmt(fps_truncate(fps(sin(sqrt(x)) / x, x))), "1/sqrt(x) - sqrt(x)/6 + x^(3/2)/120 - x^(5/2)/5040 + x^(7/2)/362880 - x^(9/2)/39916800 + x^(11/2)/6227020800 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(sin(sqrt(x)) * x, x))), "x^(3/2) - x^(5/2)/6 + x^(7/2)/120 - x^(9/2)/5040 + x^(11/2)/362880 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(atan(sqrt(x)) / x ^ 2, x))), "x^(-3/2) - 1/(3*sqrt(x)) + sqrt(x)/5 - x^(3/2)/7 + x^(5/2)/9 - x^(7/2)/11 + x^(9/2)/13 - x^(11/2)/15 + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(exp(sqrt(x)), x))), "1 + x*(sqrt(x)/6 + 1/2) + x^2*(sqrt(x)/120 + 1/24) + x^3*(sqrt(x)/5040 + 1/720) + x^4*(sqrt(x)/362880 + 1/40320) + x^5*(sqrt(x)/39916800 + 1/3628800) + sqrt(x) + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(exp(sqrt(x)) * x, x))), "x + x^2*(sqrt(x)/6 + 1/2) + x^3*(sqrt(x)/120 + 1/24) + x^4*(sqrt(x)/5040 + 1/720) + x^5*(sqrt(x)/362880 + 1/40320) + x^(3/2) + O(x^6)")
  expect_equal(mi_fmt(fps_truncate(fps(x ^ n * sin(x ^ 2), x), 8)), "-x^(n + 6)/6 + x^(n + 2) + O(x^(n + 8))")
  expect_equal(mi_fmt(fps_truncate(fps((x - 2) ^ n * log(1 + x), x, 2))), "(x - 2)^(n + 5)/1215 - (x - 2)^(n + 4)/324 + (x - 2)^(n + 3)/81 - (x - 2)^(n + 2)/18 + (x - 2)^(n + 1)/3 + (x - 2)^n*log(3) + O((x - 2)^(n + 6), (x, 2))")
  expect_equal(mi_fmt(fps_truncate(fps(x ^ (n - 2) * cos(x), x))), "x^(n + 2)/24 + x^(n - 2) - x^n/2 + O(x^(n + 4))")
  expect_equal(mi_fmt(fps_truncate(fps(x ^ (n - 2) * sin(x) + x ^ n * exp(x), x))), "x^(n + 5)/60 + x^(n + 4)/24 + x^(n + 2)/2 + x^(n + 1) + x^(n - 1) + x^n + O(x^(n + 6))")
  expect_equal(mi_fmt(fps_truncate(fps(x ^ n * atan(x), x, oo))), "x^(n - 3)/3 - x^(n - 5)/5 + x^n*(pi/2 - 1/x) + O(x^(n - 6), (x, oo))")
  expect_equal(mi_fmt(fps_truncate(fps(x ^ (n / 2) * cos(x), x))), "x^(n/2 + 4)/24 - x^(n/2 + 2)/2 + x^(n/2) + O(x^(n/2 + 6))")
  expect_equal(mi_fmt(fps_truncate(fps(x * exp(x) * sin(2 * x), x))), "2*x^2 + 2*x^3 - x^4/3 - x^5 + O(x^6)")
})
